    sub.u32 %r17, %r14, %r16;
    add.u32 %r18, %r10, %r15;
    add.u32 %r19, %r12, %r17;

    mad.lo.u32 %r20, %r9, 3, %r13;
    mul.lo.u32 %r20, %r20, %r2;
    add.u32 %r20, %r20, %r18;
    mul.lo.u32 %r20, %r20, %r3;
    add.u32 %r20, %r20, %r19;
    mul.wide.u32 %rd3, %r20, 2;
