    ld.global.u16 %h0, [%rd3];
    cvt.f32.bf16 %f1, %h0;

    mad.lo.u32 %r21, %r8, 3, %r13;
    mad.lo.u32 %r21, %r21, 3, %r15;
    mad.lo.u32 %r21, %r21, 3, %r17;
    mul.wide.u32 %rd4, %r21, 2;
    add.u64 %rd4, %rd1, %rd4;
    ld.global.u16 %h1, [%rd4];
    cvt.f32.bf16 %f2, %h1;

