        block_x = 256
        grid_x = (total_spatial + block_x - 1) // block_x
        module.launch(
            "conv3x3_bf16_kernel",
            grid=(grid_x, oc, b),
            block=(block_x, 1, 1),
            arguments=[x, weight, out, u32(total_spatial), u32(ow), u32(h), u32(w)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
